<template><div class="page"><Header/><main><h1>Request after-sales service</h1><p v-if="state==='loading'">Loading order…</p><p v-else-if="state==='error'" class="error">{{error}} <button @click="load">Retry</button></p><template v-else-if="order"><section class="card"><h2>Order {{order.orderNo||order.orderId}}</h2><article v-for="item in order.items||[]" :key="String(item.orderItemId||item.goodsId||item.skuId)"><input v-if="kind==='RETURN'" type="checkbox" :value="item.orderItemId" v-model="selectedIds" :disabled="!item.orderItemId"><strong>{{item.goodsName||'Unnamed product'}}</strong><small>{{item.specText||''}} · Quantity {{item.quantity||0}}</small><b>{{money(item.lineAmount??item.unitPrice,order.currency)}}</b></article></section><section class="card"><h2>Application details</h2><label>Type<select v-model="kind"><option value="CANCEL">Cancel order</option><option value="RETURN">Return items</option></select></label><p v-if="kind==='RETURN'&&!returnItemsAvailable" class="error">Cannot submit a return: orderItemId is missing from order data.</p><label>Reason<select v-model="reason"><option value="">Select a reason</option><option value="DAMAGED">Damaged or defective</option><option value="NOT_AS_DESCRIBED">Not as described</option><option value="OTHER">Other</option></select></label><label>Additional information<textarea v-model="note" maxlength="1000"/></label><label>Refund method<input v-model="refundMethod" placeholder="Enter refund method"/></label><p class="hint">Photo upload is unavailable: no upload endpoint/result URL contract is configured. Local file URLs are not submitted.</p><p v-if="message" :class="failed?'error':'success'">{{message}}</p><button class="primary" @click="submit" :disabled="saving||!canSubmit">{{saving?'Submitting…':'Submit request'}}</button><button @click="router.back()">Cancel</button></section></template></main><Footer/></div></template>
<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import Header from '@/components/Header.vue';import Footer from '@/components/Footer.vue';import {getOrderDetail,saveAfterSale,type OrderRecord} from '@/api/orders';import {getCustomerAuthState} from '@/utils/customerAuth'
const route=useRoute(),router=useRouter(),order=ref<OrderRecord|null>(null),state=ref<'loading'|'success'|'error'>('loading'),error=ref(''),kind=ref<'CANCEL'|'RETURN'>('CANCEL'),reason=ref(''),note=ref(''),refundMethod=ref(''),selectedIds=ref<Array<string|number>>([]),saving=ref(false),message=ref(''),failed=ref(false),afterSaleId=ref<string|number|null>(null)
const returnItemsAvailable=computed(()=>Boolean(order.value?.items?.length)&&order.value!.items!.every(item=>item.orderItemId!==undefined&&item.orderItemId!==null&&String(item.orderItemId)!==''));const canSubmit=computed(()=>Boolean(order.value&&reason.value&&getCustomerAuthState().isAuthenticated&&(kind.value==='CANCEL'||(returnItemsAvailable.value&&selectedIds.value.length>0))))
async function load(){if(!getCustomerAuthState().isAuthenticated){state.value='error';error.value='Please sign in with a customer account.';return}state.value='loading';try{order.value=await getOrderDetail(String(route.params.id||''));state.value='success'}catch(e){state.value='error';error.value=e instanceof Error?e.message:'Unable to load order.'}}
function money(value:any,currency='USD'){if(value===undefined||value===null||value==='')return'—';const n=Number(value);return Number.isFinite(n)?new Intl.NumberFormat(undefined,{style:'currency',currency:currency||'USD'}).format(n):String(value)}
async function submit(){if(saving.value||!canSubmit.value||!order.value)return;saving.value=true;message.value='';failed.value=false;try{const result:any=await saveAfterSale(String(order.value.orderId),{kind:kind.value,reason:reason.value,...(note.value?{note:note.value}:{}),...(refundMethod.value?{refundMethod:refundMethod.value}:{}),...(kind.value==='RETURN'?{items:selectedIds.value.map(orderItemId=>({orderItemId,quantity:1}))}:{})});afterSaleId.value=result?.afterSaleId??result?.data?.afterSaleId??null;if(afterSaleId.value===null)throw new Error('No afterSaleId in successful response; verify the request before retrying.');message.value='After-sales request submitted. Reference: '+String(afterSaleId.value)}catch(e){failed.value=true;message.value=e instanceof Error?e.message:'Unable to submit request.'}finally{saving.value=false}}
onMounted(load)
</script>
<style scoped>.page{min-height:100vh;background:#f4f4f5;color:#333;font:13px Arial}.page main{max-width:900px;margin:24px auto;padding:0 16px}.page h1{font-size:18px}.card{background:white;border:1px solid #e2e5e8;border-radius:6px;padding:16px;margin:12px 0}.card h2{font-size:15px}.card article{display:flex;gap:12px;align-items:center;border-top:1px solid #eee;padding:12px 0;overflow-wrap:anywhere}.card article small{color:#6b7280}.card label{display:flex;flex-direction:column;gap:6px;margin:12px 0}.card select,.card input,.card textarea{min-height:36px;border:1px solid #d1d5db;border-radius:4px;padding:8px;font:13px Arial}.card textarea{min-height:90px}.primary{background:#333;color:white;border:0;border-radius:4px;padding:9px 16px;margin-right:8px}.primary:disabled{opacity:.5}.error{color:#a63805}.success{color:#18794e}.hint{color:#6b7280}@media(max-width:650px){.page main{margin:12px auto}.card{padding:12px}}</style>